('e30cf82a-bc91-4d37-88ea-d43806fbce20', 'd3b07384-d113-4952-b1cf-9a993710787e', 'Quote Sent WhatsApp', 'WHATSAPP', 'QUOTE_SENT', NULL, 'Namaste {{clientName}}! Thank you for reaching out. We have sent the custom quotation for {{projectTitle}} to your email/chat. You can review and accept it here: {{quotationLink}}.\n\nLooking forward to covering your special days! 😊', true),
('e30cf82a-bc91-4d37-88ea-d43806fbce21', 'd3b07384-d113-4952-b1cf-9a993710787e', 'Soft WhatsApp Follow-up', 'WHATSAPP', 'SOFT_FOLLOW_UP', NULL, 'Namaste {{clientName}}! Hope you are doing well. Just wanted to make sure you received the custom quotation for {{projectTitle}} we sent yesterday. Do you have any quick questions about the package inclusions or customized video editing? 😊', true),
('e30cf82a-bc91-4d37-88ea-d43806fbce22', 'd3b07384-d113-4952-b1cf-9a993710787e', 'Value Follow-up WhatsApp', 'WHATSAPP', 'VALUE_FOLLOW_UP', NULL, 'Hi {{clientName}}! Planning your wedding photography details? Here is a quick link to some of our recent wedding stories & customer testimonials: {{testimonialLink}}.\n\nWe would love to capture your beautiful celebrations! 📸', true),
('e30cf82a-bc91-4d37-88ea-d43806fbce23', 'd3b07384-d113-4952-b1cf-9a993710787e', 'Scarcity WhatsApp Follow-up', 'WHATSAPP', 'SCARCITY_FOLLOW_UP', NULL, 'Hi {{clientName}}! We just received another inquiry for {{eventDate}} (peak wedding season). Since your quotation is still active, we wanted to check if you are ready to book so we can lock in the date for you! Reply here to proceed.', true),
('e30cf82a-bc91-4d37-88ea-d43806fbce24', 'd3b07384-d113-4952-b1cf-9a993710787e', 'Final Closure WhatsApp', 'WHATSAPP', 'FINAL_FOLLOW_UP', NULL, 'Hi {{clientName}}, this is {{studioName}}. We have not heard back regarding our quotation, so we will close it out to release the date for other inquiries. Thank you! 🙏', true);
