('a0000000-0000-0000-0000-000000000004', 'd3b07384-d113-4952-b1cf-9a993710787e', '3a0cf82a-bc91-4d37-88ea-d43806fbce30', 'f8df4a4a-1123-4ad9-a78f-efbcd8213e44', 'e30cf82a-bc91-4d37-88ea-d43806fbce23', 'WHATSAPP', CURRENT_TIMESTAMP + INTERVAL '1 day', 'PENDING_APPROVAL', '+919800000010', NULL, 'Hi Vikram Rao! We just received another inquiry for 2026-07-10 (peak wedding season). Since your quotation is still active, we wanted to check if you are ready to book so we can lock in the date for you! Reply here to proceed.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('a0000000-0000-0000-0000-000000000005', 'd3b07384-d113-4952-b1cf-9a993710787e', '3a0cf82a-bc91-4d37-88ea-d43806fbce30', 'f8df4a4a-1123-4ad9-a78f-efbcd8213e45', 'e30cf82a-bc91-4d37-88ea-d43806fbce24', 'WHATSAPP', CURRENT_TIMESTAMP + INTERVAL '3 days', 'PENDING_APPROVAL', '+919800000011', NULL, 'Hi Rohan Mehta, this is Default Studio. We have not heard back regarding our quotation, so we will close it out to release the date for other inquiries. Thank you! 🙏', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
