('a0000000-0000-0000-0000-000000000007', 'd3b07384-d113-4952-b1cf-9a993710787e', '3a0cf82a-bc91-4d37-88ea-d43806fbce30', 'f8df4a4a-1123-4ad9-a78f-efbcd8213e42', 'e30cf82a-bc91-4d37-88ea-d43806fbce21', 'WHATSAPP', CURRENT_TIMESTAMP - INTERVAL '4 days', 'SENT', '+919800000012', NULL, 'Namaste Divya Joshi! Hope you are doing well. Just wanted to make sure you received the custom quotation for Cocktail Party Shoot we sent yesterday. Do you have any quick questions about the package inclusions or customized video editing? 😊', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
