('a0000000-0000-0000-0000-000000000009', 'd3b07384-d113-4952-b1cf-9a993710787e', '3a0cf82a-bc91-4d37-88ea-d43806fbce30', 'f8df4a4a-1123-4ad9-a78f-efbcd8213e41', 'e30cf82a-bc91-4d37-88ea-d43806fbce20', 'WHATSAPP', CURRENT_TIMESTAMP - INTERVAL '3 days', 'SENT', '+919800000025', NULL, 'Namaste Aditi Rao! Thank you for reaching out. We have sent the custom quotation for Haldi Ceremony to your email/chat. You can review and accept it here: http://localhost:5173/quotations/review/25.\n\nLooking forward to covering your special days! 😊', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('a0000000-0000-0000-0000-000000000010', 'd3b07384-d113-4952-b1cf-9a993710787e', '3a0cf82a-bc91-4d37-88ea-d43806fbce30', 'f8df4a4a-1123-4ad9-a78f-efbcd8213e42', 'e30cf82a-bc91-4d37-88ea-d43806fbce21', 'WHATSAPP', CURRENT_TIMESTAMP - INTERVAL '1 day', 'PENDING_APPROVAL', '+919800000025', NULL, 'Namaste Aditi Rao! Hope you are doing well. Just wanted to make sure you received the custom quotation for Haldi Ceremony we sent yesterday. Do you have any quick questions about the package inclusions or customized video editing? 😊', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
